1	//! End-to-end regression coverage for file paths that are not valid UTF-8.
2	//!
3	//! On Unix a file name (or any parent component) may contain bytes such as
4	//! 0xff that do not form valid UTF-8. Such a path is not invalid: the file
5	//! system accepts it and the program must open exactly the path bytes the
6	//! user passed, instead of aborting while collecting command line arguments
7	//! or opening a differently named file whose rendered name looks the same.
8	//!
9	//! These tests exercise the built binary directly with raw `OsStr`
10	//! arguments. They are Unix-only because non-Unicode file names are a
11	//! Unix-only concept.
12	
13	#![cfg(unix)]
14	
15	use std::fs;
16	use std::os::unix::ffi::OsStrExt;
17	use std::path::{Path, PathBuf};
18	use std::process::Command;
19	use std::sync::atomic::{AtomicU64, Ordering};
20	
21	static COUNTER: AtomicU64 = AtomicU64::new(0);
22	
23	fn bin() -> &'static str {
24	    env!("CARGO_BIN_EXE_roottrace")
25	}
26	
27	/// Scratch directory deleted on drop, even if the test panics.
28	struct TempDir {
29	    path: PathBuf,
30	}
31	
32	impl TempDir {
33	    fn create() -> Self {
34	        let id = COUNTER.fetch_add(1, Ordering::Relaxed);
35	        let path = std::env::temp_dir().join(format!(
36	            "roottrace-nonutf8-{}-{}",
37	            std::process::id(),
38	            id
39	        ));
40	        fs::create_dir(&path).unwrap();
41	        TempDir { path }
42	    }
43	
44	    fn child(&self, name: &[u8]) -> PathBuf {
45	        self.path.join(std::ffi::OsStr::from_bytes(name))
46	    }
47	
48	    fn write(&self, name: &[u8], data: &[u8]) -> PathBuf {
49	        let path = self.child(name);
50	        fs::write(&path, data).unwrap();
51	        path
52	    }
53	}
54	
55	impl Drop for TempDir {
56	    fn drop(&mut self) {
57	        let _ = fs::remove_dir_all(&self.path);
58	    }
59	}
60	
61	fn run(args: &[&[u8]], current_dir: Option<&Path>) -> std::process::Output {
62	    let mut cmd = Command::new(bin());
63	    for arg in args {
64	        cmd.arg(std::ffi::OsStr::from_bytes(arg));
65	    }
66	    if let Some(dir) = current_dir {
67	        cmd.current_dir(dir);
68	    }
69	    cmd.output().unwrap()
70	}
71	
72	// Batch content exercising every content-preservation rule: a trailing CR,
73	// a NUL byte, non-UTF-8 record bytes and a terminating LF.
74	const CONTENT: &[u8] = b"alpha\r\n\x00nul-record\n\xff\xfebinary\n";
75	
76	/// `root` over a 0xff-named file must match the ASCII-named twin byte for
77	/// byte and must not touch stderr.
78	#[test]
79	fn root_accepts_non_utf8_file_name_and_parent_directory() {
80	    let dir = TempDir::create();
81	    let ascii_path = dir.write(b"ascii.txt", CONTENT);
82	    let weird_path = dir.write(b"weird-\xff-name.txt", CONTENT);
83	    let ascii_out = run(&[b"root", ascii_path.as_os_str().as_bytes()], None);
84	    assert_eq!(ascii_out.status.code(), Some(0));
85	    assert!(ascii_out.stderr.is_empty());
86	
87	    let weird_out = run(&[b"root", weird_path.as_os_str().as_bytes()], None);
88	    assert_eq!(weird_out.status.code(), Some(0), "{:?}", weird_out.stderr);
89	    assert!(weird_out.stderr.is_empty());
90	    assert_eq!(weird_out.stdout, ascii_out.stdout);
91	    assert_eq!(weird_out.stdout.len(), 65);
92	
93	    // A parent component carrying 0xff must work for both relative and
94	    // absolute spellings.
95	    let sub = dir.child(b"sub-\xff");
96	    fs::create_dir(&sub).unwrap();
97	    let nested = sub.join(std::ffi::OsStr::from_bytes(b"batch-\xfe.txt"));
98	    fs::write(&nested, CONTENT).unwrap();
99	
100	    let abs_out = run(&[b"root", nested.as_os_str().as_bytes()], None);
101	    assert_eq!(abs_out.status.code(), Some(0), "{:?}", abs_out.stderr);
102	    assert!(abs_out.stderr.is_empty());
103	    assert_eq!(abs_out.stdout, ascii_out.stdout);
104	
105	    let rel_out = run(&[b"root", b"./batch-\xfe.txt"], Some(&sub));
106	    assert_eq!(rel_out.status.code(), Some(0), "{:?}", rel_out.stderr);
107	    assert!(rel_out.stderr.is_empty());
108	    assert_eq!(rel_out.stdout, ascii_out.stdout);
109	}
110	
111	/// The raw 0xff bytes must reach the filesystem untouched. A sibling whose
112	/// name contains the replacement character U+FFFD displays the same under
113	/// lossy conversion but is a different file with different content; it must
114	/// never be read by mistake.
115	#[test]
116	fn raw_path_bytes_are_not_confused_with_a_replacement_character_file() {
117	    let dir = TempDir::create();
118	    let real = dir.write(b"real-\xff.bin", b"correct-a\ncorrect-b\ncorrect-c\n");
119	    // U+FFFD encoded as UTF-8 is ef bf bd: a distinct file name that merely
120	    // renders the same as the 0xff name under lossy conversion.
121	    let mut decoy_bytes: Vec<u8> = b"real-".to_vec();
122	    decoy_bytes.extend_from_slice("\u{FFFD}".as_bytes());
123	    decoy_bytes.extend_from_slice(b".bin");
124	    let decoy = dir.write(&decoy_bytes, b"decoy-a\ndecoy-b\ndecoy-c\n");
125	    assert_ne!(real, decoy);
126	
127	    let real_out = run(&[b"root", real.as_os_str().as_bytes()], None);
128	    assert_eq!(real_out.status.code(), Some(0));
129	    let decoy_out = run(&[b"root", decoy.as_os_str().as_bytes()], None);
130	    assert_eq!(decoy_out.status.code(), Some(0));
131	    assert_ne!(
132	        real_out.stdout, decoy_out.stdout,
133	        "the U+FFFD-named file has different content and must hash differently"
134	    );
135	
136	    for index in [b"0".as_slice(), b"1".as_slice(), b"2".as_slice()] {
137	        let real_proof = run(
138	            &[b"prove", real.as_os_str().as_bytes(), index],
139	            None,
140	        );
141	        assert_eq!(real_proof.status.code(), Some(0), "{:?}", real_proof.stderr);
142	        let decoy_proof = run(
143	            &[b"prove", decoy.as_os_str().as_bytes(), index],
144	            None,
145	        );
146	        assert_eq!(decoy_proof.status.code(), Some(0), "{:?}", decoy_proof.stderr);
147	        assert_ne!(real_proof.stdout, decoy_proof.stdout);
148	    }
149	}
150	
151	/// `prove` results for identical content must be identical regardless of the
152	/// path bytes used to name the file, at every record position.
153	#[test]
154	fn prove_results_are_identical_across_path_byte_variants() {
155	    let dir = TempDir::create();
156	    let ascii_path = dir.write(b"ascii.txt", CONTENT);
157	    let weird_path = dir.write(b"weird-\xff.txt", CONTENT);
158	    for index in [b"0".as_slice(), b"1".as_slice(), b"2".as_slice()] {
159	        let a = run(&[b"prove", ascii_path.as_os_str().as_bytes(), index], None);
160	        let w = run(&[b"prove", weird_path.as_os_str().as_bytes(), index], None);
161	        assert_eq!(a.status.code(), Some(0), "{:?}", a.stderr);
162	        assert_eq!(w.status.code(), Some(0), "{:?}", w.stderr);
163	        assert!(a.stderr.is_empty() && w.stderr.is_empty());
164	        assert_eq!(w.stdout, a.stdout, "index {:?}", index);
165	    }
166	    // A valid index past the end of a non-UTF-8-named file is still a
167	    // position error (exit 1), not a usage error.
168	    let missing_pos = run(
169	        &[b"prove", weird_path.as_os_str().as_bytes(), b"3"],
170	        None,
171	    );
172	    assert_eq!(missing_pos.status.code(), Some(1));
173	    assert!(missing_pos.stdout.is_empty());
174	    let err = String::from_utf8_lossy(&missing_pos.stderr);
175	    assert!(err.contains("does not exist"), "{err}");
176	}
177	
178	/// A missing or directory path that itself contains 0xff must produce the
179	/// stable read-failure contract: exit 1, empty stdout, a message on stderr,
180	/// and no panic.
181	#[test]
182	fn non_utf8_read_failures_exit_1_without_panicking() {
183	    let dir = TempDir::create();
184	    let missing = dir.child(b"no-such-\xff-file");
185	    let missing_bytes = missing.as_os_str().as_bytes();
186	    for args in [
187	        vec![b"root".as_slice(), missing_bytes],
188	        vec![b"prove".as_slice(), missing_bytes, b"0"],
189	    ] {
190	        let out = run(&args, None);
191	        assert_eq!(out.status.code(), Some(1), "args {args:?}");
192	        assert!(out.stdout.is_empty(), "args {args:?}");
193	        assert!(!out.stderr.is_empty(), "args {args:?}");
194	    }
195	
196	    let sub = dir.child(b"dir-\xff");
197	    fs::create_dir(&sub).unwrap();
198	    let sub_bytes = sub.as_os_str().as_bytes();
199	    for args in [
200	        vec![b"root".as_slice(), sub_bytes],
201	        vec![b"prove".as_slice(), sub_bytes, b"0"],
202	    ] {
203	        let out = run(&args, None);
204	        assert_eq!(out.status.code(), Some(1), "args {args:?}");
205	        assert!(out.stdout.is_empty(), "args {args:?}");
206	        assert!(!out.stderr.is_empty(), "args {args:?}");
207	    }
208	}
209	
210	/// `verify` works end to end with 0xff-named record and proof files: the
211	/// record bytes (including non-UTF-8 content) and the raw path bytes are both
212	/// handled exactly. The trusted size/root are fetched through `root`, never
213	/// from fields of the proof under test.
214	#[test]
215	fn verify_accepts_non_utf8_record_and_proof_paths_and_content() {
216	    let dir = TempDir::create();
217	    // CONTENT splits (LF rule) into: "alpha\r", "\x00nul-record",
218	    // "\xff\xfebinary". The last record is itself non-UTF-8.
219	    let batch = dir.write(b"batch-\xff.txt", CONTENT);
220	
221	    let root_out = run(&[b"root", batch.as_os_str().as_bytes()], None);
222	    assert_eq!(root_out.status.code(), Some(0));
