    // Removing only the SECOND copy of the duplicated content (position 5):
    // identical bytes still present at position 3 must not be merged away.
    root_of_file_bytes(
        "CHUNK_NO_DUP",
        &join_lf_owned(&chunk_records_subset(&long, |i| i != 5), false),
        ROOT_CHUNK_NO_DUP,
