    // multi-read long record and must take part in the final root.
    root_of_file_bytes(
        "CHUNK_NO_TAIL",
        &join_lf_owned(&chunk_records_subset(&long, |i| i != 6), false),
        ROOT_CHUNK_NO_TAIL,
